class PropScan:
    """Main scanner class."""

    def __init__(self):
        self.managers = [
            FlatpakManager(),
            PacmanManager(),
            AptManager(),
            DnfManager(),
        ]
        self.detector = LicenseBasedDetector()

    def get_available_managers(self) -> List[PackageManager]:
        """Get list of available package managers."""
        return [manager for manager in self.managers if manager.is_available()]

    def scan_manager(self, manager: PackageManager) -> List[Dict[str, any]]:
        """Scan a specific package manager for proprietary software."""
        packages = manager.get_installed_packages()
        proprietary = []

        for package in packages:
            if self.detector.is_proprietary(package):
                # Add detection reason for transparency
                package["detection_reason"] = self.detector.get_detection_reason(package)
                proprietary.append(package)

        return proprietary

    def scan_all(self, manager_filter: Optional[str] = None) -> Dict[str, List[Dict[str, any]]]:
        """Scan all available package managers."""
        results = {}
        available_managers = self.get_available_managers()

        for manager in available_managers:
            if manager_filter and manager.name.lower() != manager_filter.lower():
                continue

            proprietary = self.scan_manager(manager)
            if proprietary:
                results[manager.name] = proprietary

        return results
